package ktanesolver.module.modded.regular.encrypted_morse;import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.*;
class EncryptedMorseSolverTest{private final EncryptedMorseSolver solver=new EncryptedMorseSolver();
	@Test void decryptsBinaryMorseAndEncodesResponse(){BombEntity bomb=bomb(0);ModuleEntity module=new ModuleEntity();EncryptedMorseOutput out=solve(bomb,module,fixture(bomb,"CDSNMZSD","AAAAAAAA"));assertThat(out.intermediateMessage()).isEqualTo("CDSNMZSD");assertThat(out.decryptedMessage()).isEqualTo("DETONATE");assertThat(out.response()).isEqualTo("PLEASENO");assertThat(out.responseMorse()).isEqualTo(EncryptedMorseSolver.encode("PLEASENO",false));assertThat(out.swapped()).isFalse();assertThat(module.getState().get("encryptedMorseKey")).isEqualTo("AAAAAAAA");}
	@Test void reversesFirstHalfWhenBatteryAndPortTotalsMatch(){BombEntity equal=bomb(0),unequal=bomb(1);String normal=EncryptedMorseSolver.sequenceB(unequal),reversed=EncryptedMorseSolver.sequenceB(equal);assertThat(reversed.substring(0,21)).isEqualTo(new StringBuilder(normal.substring(0,21)).reverse().toString());assertThat(reversed.substring(21)).isEqualTo(normal.substring(21));}
	@Test void appliesTheTwoPositionSwapsToMessageAndKey(){BombEntity bomb=bomb(1);String call="REMEMBER",originalMessage="AEIOUBCD",originalKey=keyFor(call,originalMessage),transmittedMessage=swap(originalMessage),transmittedKey=swap(originalKey);EncryptedMorseOutput out=solve(bomb,new ModuleEntity(),fixture(bomb,transmittedMessage,transmittedKey));assertThat(out.swapped()).isTrue();assertThat(out.decryptedMessage()).isEqualTo(call);assertThat(out.response()).isEqualTo("SOUVENIR");}
	@Test void rejectsMalformedObservations(){BombEntity bomb=bomb(1);assertThat(solver.solve(new RoundEntity(),bomb,new ModuleEntity(),new EncryptedMorseInput("101","E","ABCDEFGH"))).isInstanceOf(SolveFailure.class);assertThat(solver.solve(new RoundEntity(),bomb,new ModuleEntity(),new EncryptedMorseInput("0".repeat(42),"E","ABC"))).isInstanceOf(SolveFailure.class);}
	private static EncryptedMorseInput fixture(BombEntity bomb,String transmittedIntermediate,String transmittedKey){String target=EncryptedMorseSolver.encode(transmittedIntermediate,true),b=EncryptedMorseSolver.sequenceB(bomb);char[]a="0".repeat(42).toCharArray();StringBuilder received=new StringBuilder();for(int i=0;i<target.length();i++){char wanted=target.charAt(i),symbol;if(wanted=='.'){a[i]='1';symbol='.';}else if(wanted=='-'){a[i]='0';symbol=b.charAt(i)=='0'?'-':'.';}else if(b.charAt(i)=='0'){a[i]='0';symbol='.';}else{a[i]='1';symbol='-';}received.append(symbol=='.'?'E':'T');}return new EncryptedMorseInput(new String(a),received.toString(),transmittedKey);}
	private static String keyFor(String call,String intermediate){StringBuilder key=new StringBuilder();for(int i=0;i<8;i++){int n=(call.charAt(i)-'A'+1)-(intermediate.charAt(i)-'A'+1);if(n<=0)n+=26;key.append((char)('A'+n-1));}return key.toString();}private static String swap(String value){char[]c=value.toCharArray();char t=c[0];c[0]=c[4];c[4]=t;t=c[1];c[1]=c[7];c[7]=t;return new String(c);}@SuppressWarnings("unchecked")private EncryptedMorseOutput solve(BombEntity bomb,ModuleEntity module,EncryptedMorseInput input){return((SolveSuccess<EncryptedMorseOutput>)solver.solve(new RoundEntity(),bomb,module,input)).output();}private static BombEntity bomb(int batteries){BombEntity b=new BombEntity();b.setSerialNumber("ABC123");b.setAaBatteryCount(batteries);return b;}}
